window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7ba5c2cfe57608cc"]={"versions": [{"id": "FIG-7ba5c2cfe57608cc", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Kontroll- und Datenflusses beim Empfang eines E2E-geschützten Datenelements auf Empfängerseite (Receiver E2E) im Kontext der AUTOSAR Classic Platform. Das Diagramm spezifiziert das Zusammenspiel zwischen einer Software-Komponente (SWC), dem E2E Protection Wrapper (E2EPW), dem RTE-Interface, der E2E Library sowie der CRC Library.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Entitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>Receiver E2E</strong>: Umfassender logischer Kontext bestehend aus:</li>\n<li><code>Receiver SWC application</code>: Aufrufende Applikations-SWC.</li>\n<li><code>Receiver E2E Protection Wrapper</code> (farblich hervorgehoben): Vermittelnde Wrapper-Schicht (<code>E2EPW</code>).</li>\n<li><code>Receiver SWC RTE Interface</code>: RTE-Laufzeitschnittstelle.</li>\n<li><code>E2E Library</code>: Bibliothek zur Durchführung von Profilprüfungen (<code>E2E_PXXCheck</code>).</li>\n<li><code>CRC Library</code>: Prüfsummen-Bibliothek (<code>crc</code>).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Aufrufe:</p>\n<ul class=\"fig-list\">\n<li>SWC zu E2EPW: <code>E2EPW_Read_&lt;p&gt;_&lt;o&gt;(&amp;dataEl)</code> mit Rückgabewert <code>ret</code>.</li>\n<li>E2EPW zu RTE: <code>Rte_Read_&lt;port&gt;_&lt;data&gt;(&amp;DataEl)</code> mit Rückgabewert <code>retRteRead</code>.</li>\n<li>E2EPW zu E2E Library: <code>E2E_PXXCheck(&amp;Config, &amp;State, &amp;Data)</code> mit Rückgabewert <code>retE2ECheck</code>.</li>\n<li>E2E Library zu CRC Library: Mehrfacher Aufruf zur Berechnung von CRC über <code>Data</code> und <code>DataID</code>.</li>\n<li>Interne E2EPW-Aktionen: Zustandszuweisung <code>State-&gt;NewDataAvailable = (retRteRead == RTE_E_OK) ? TRUE : FALSE</code>, Serialisierung in I-PDU-Replikarray <code>(&amp;AppDataEl, &amp;Data)</code>, Deserialisierungsüberprüfung (Vorzeichenerweiterung, Wertebereiche), Kombination der Rückgabe- und Statuswerte (<code>ret = combination of (return) values Rte_Read_&lt;p&gt;_&lt;o&gt; (..), E2E_PXXCheck (..), State-&gt;Status, deserialization valid</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenzablauf in neun Schritten:</p>\n<ol class=\"fig-list\">\n<li><strong>Step R1</strong>: Die SWC ruft <code>E2EPW_Read_&lt;p&gt;_&lt;o&gt;(&amp;dataEl)</code> anstelle von <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(..)</code> mit identischen Parametern auf.</li>\n<li><strong>Step R2</strong>: E2EPW ruft <code>Rte_Read_&lt;port&gt;_&lt;data&gt;(&amp;DataEl)</code> am RTE-Interface auf und empfängt die aktuellen Rohdaten sowie <code>retRteRead</code>.</li>\n<li><strong>Step R3</strong>: E2EPW setzt <code>State-&gt;NewDataAvailable</code> auf <code>TRUE</code>, falls <code>retRteRead == RTE_E_OK</code>, andernfalls auf <code>FALSE</code>.</li>\n<li><strong>Step R4</strong>: E2EPW serialisiert das Datenelement in ein I-PDU-Replika-Array (<code>&amp;AppDataEl</code>, <code>&amp;Data</code>).</li>\n<li><strong>Step R5</strong>: E2EPW ruft <code>E2E_PXXCheck(&amp;Config, &amp;State, &amp;Data)</code> der E2E Library auf.</li>\n<li><strong>Step R6</strong>: Die E2E Library berechnet Prüfsummen über wiederholte Aufrufe der CRC Library, verifiziert CRC, Alive-Counter und <code>NewDataAvailable</code>, aktualisiert den Zustand (<code>update State</code>) und gibt <code>retE2ECheck</code> zurück.</li>\n<li><strong>Step R7</strong>: E2EPW validiert die Deserialisierung durch das COM-Modul (Prüfung von Wertebereichen und Vorzeichenerweiterung: <code>bool</code>).</li>\n<li><strong>Step R8</strong>: E2EPW kombiniert <code>retRteRead</code>, <code>retE2ECheck</code>, <code>State-&gt;Status</code> sowie das Deserialisierungs-Prüfergebnis zu <code>ret</code> und liefert dieses an die SWC zurück.</li>\n<li><strong>Step R9</strong>: Die SWC prüft den Rückgabewert <code>ret</code> und entscheidet über die Nutzbarkeit von <code>DataEl</code> oder die Auslösung einer Fehlerreaktion.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der E2E Protection Wrapper abstrahiert die E2E-Prüfungen transparent für die Anwendungs-SWC, erfordert jedoch eine komplementäre Serialisierung des von der RTE empfangenen Datenelements, um die I-PDU-Prüfsummenprüfung der E2E Library zu ermöglichen. Entwickler müssen sicherstellen, dass sowohl Kommunikationsfehler (RTE) als auch Protokollfehler (E2E) und Deserialisierungsfehler im Rückgabestatus aggregiert und von der SWC deterministisch ausgewertet werden.</p>"}, {"id": "FIG-8c49bc23cdfbb8c3", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Kontroll- und Datenflusses beim Empfang eines E2E-geschützten Datenelements auf Empfängerseite (Receiver E2E) im Kontext der AUTOSAR Classic Platform. Das Diagramm spezifiziert das Zusammenspiel zwischen einer Software-Komponente (SWC), dem E2E Protection Wrapper (E2EPW), dem RTE-Interface, der E2E Library sowie der CRC Library.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Entitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>Receiver E2E</strong>: Umfassender logischer Kontext bestehend aus:</li>\n<li><code>Receiver SWC application</code>: Aufrufende Applikations-SWC.</li>\n<li><code>Receiver E2E Protection Wrapper</code> (farblich hervorgehoben): Vermittelnde Wrapper-Schicht (<code>E2EPW</code>).</li>\n<li><code>Receiver SWC RTE Interface</code>: RTE-Laufzeitschnittstelle.</li>\n<li><code>E2E Library</code>: Bibliothek zur Durchführung von Profilprüfungen (<code>E2E_PXXCheck</code>).</li>\n<li><code>CRC Library</code>: Prüfsummen-Bibliothek (<code>crc</code>).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Aufrufe:</p>\n<ul class=\"fig-list\">\n<li>SWC zu E2EPW: <code>E2EPW_Read_&lt;p&gt;_&lt;o&gt;(&amp;dataEl)</code> mit Rückgabewert <code>ret</code>.</li>\n<li>E2EPW zu RTE: <code>Rte_Read_&lt;port&gt;_&lt;data&gt;(&amp;DataEl)</code> mit Rückgabewert <code>retRteRead</code>.</li>\n<li>E2EPW zu E2E Library: <code>E2E_PXXCheck(&amp;Config, &amp;State, &amp;Data)</code> mit Rückgabewert <code>retE2ECheck</code>.</li>\n<li>E2E Library zu CRC Library: Mehrfacher Aufruf zur Berechnung von CRC über <code>Data</code> und <code>DataID</code>.</li>\n<li>Interne E2EPW-Aktionen: Zustandszuweisung <code>State-&gt;NewDataAvailable = (retRteRead == RTE_E_OK) ? TRUE : FALSE</code>, Serialisierung in I-PDU-Replikarray <code>(&amp;AppDataEl, &amp;Data)</code>, Deserialisierungsüberprüfung (Vorzeichenerweiterung, Wertebereiche), Kombination der Rückgabe- und Statuswerte (<code>ret = combination of (return) values Rte_Read_&lt;p&gt;_&lt;o&gt; (..), E2E_PXXCheck (..), State-&gt;Status, deserialization valid</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenzablauf in neun Schritten:</p>\n<ol class=\"fig-list\">\n<li><strong>Step R1</strong>: Die SWC ruft <code>E2EPW_Read_&lt;p&gt;_&lt;o&gt;(&amp;dataEl)</code> anstelle von <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(..)</code> mit identischen Parametern auf.</li>\n<li><strong>Step R2</strong>: E2EPW ruft <code>Rte_Read_&lt;port&gt;_&lt;data&gt;(&amp;DataEl)</code> am RTE-Interface auf und empfängt die aktuellen Rohdaten sowie <code>retRteRead</code>.</li>\n<li><strong>Step R3</strong>: E2EPW setzt <code>State-&gt;NewDataAvailable</code> auf <code>TRUE</code>, falls <code>retRteRead == RTE_E_OK</code>, andernfalls auf <code>FALSE</code>.</li>\n<li><strong>Step R4</strong>: E2EPW serialisiert das Datenelement in ein I-PDU-Replika-Array (<code>&amp;AppDataEl</code>, <code>&amp;Data</code>).</li>\n<li><strong>Step R5</strong>: E2EPW ruft <code>E2E_PXXCheck(&amp;Config, &amp;State, &amp;Data)</code> der E2E Library auf.</li>\n<li><strong>Step R6</strong>: Die E2E Library berechnet Prüfsummen über wiederholte Aufrufe der CRC Library, verifiziert CRC, Alive-Counter und <code>NewDataAvailable</code>, aktualisiert den Zustand (<code>update State</code>) und gibt <code>retE2ECheck</code> zurück.</li>\n<li><strong>Step R7</strong>: E2EPW validiert die Deserialisierung durch das COM-Modul (Prüfung von Wertebereichen und Vorzeichenerweiterung: <code>bool</code>).</li>\n<li><strong>Step R8</strong>: E2EPW kombiniert <code>retRteRead</code>, <code>retE2ECheck</code>, <code>State-&gt;Status</code> sowie das Deserialisierungs-Prüfergebnis zu <code>ret</code> und liefert dieses an die SWC zurück.</li>\n<li><strong>Step R9</strong>: Die SWC prüft den Rückgabewert <code>ret</code> und entscheidet über die Nutzbarkeit von <code>DataEl</code> oder die Auslösung einer Fehlerreaktion.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der E2E Protection Wrapper abstrahiert die E2E-Prüfungen transparent für die Anwendungs-SWC, erfordert jedoch eine komplementäre Serialisierung des von der RTE empfangenen Datenelements, um die I-PDU-Prüfsummenprüfung der E2E Library zu ermöglichen. Entwickler müssen sicherstellen, dass sowohl Kommunikationsfehler (RTE) als auch Protokollfehler (E2E) und Deserialisierungsfehler im Rückgabestatus aggregiert und von der SWC deterministisch ausgewertet werden.</p>"}], "trans": [{"from": "FIG-7ba5c2cfe57608cc", "to": "FIG-8c49bc23cdfbb8c3", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
